def transform (grid :list [list [int ]])->list [list [int ]]:
    import numpy as np
    arr =np .array (grid )
    components =connected_components (arr ,connectivity =8 ,background =0 )
    for i in range (len (components )):
        for j in range (len (components )):
            if i ==j :
                continue
            inner =components [i ]
            container =components [j ]
            if in_cavity (inner ,container ):
                return [[int (inner .color )]]
    return [[0 ]]

