import numpy as np
def transform (grid :list [list [int ]])->list [list [int ]]:
    arr =np .array (grid )
    components =connected_components (arr ,connectivity =4 ,background =0 )
    for container in components :
        for candidate in components :
            if container ==candidate :
                continue
            if in_cavity (candidate ,container ):
                return [[int (candidate .color )]]
